def seed_portal_content(apps, schema_editor):
    from django.utils.text import slugify

    Service = apps.get_model("services", "Service")
    FaqItem = apps.get_model("services", "FaqItem")

    FaqItem.objects.bulk_create([
        FaqItem(question=q, answer=a, display_order=i) for i, (q, a) in enumerate(SAMPLE_FAQS, start=1)
    ])

    # Swap in the new sample services only when the old untouched demos are all that exist.
    existing = list(Service.objects.values_list("slug", "url"))
    is_old_demo = all(slug in OLD_DEMO_SLUGS and url.startswith("https://example.com/") for slug, url in existing)
    if is_old_demo:
        Service.objects.all().delete()
        Service.objects.bulk_create([
            Service(name=n, slug=slugify(n), category=c, color=col, is_published=pub,
                    description=d, url=u, display_order=i)
            for i, (n, c, col, pub, d, u) in enumerate(SAMPLE_SERVICES, start=1)
        ])


